// th14_s2_w05: TH14 v1.00b Stage 2 道中奖励波 st02.ecl.txt::MainSub04 (720-742)
// 依赖: st02.ecl.txt::GirlB01 (272-297), GirlB01_at (299-339); default.ecl.txt::DeadAttack2/DeadAttackEt1 未被调用（见 report）
// 弹型: TH14 原 type0-23 同号映射; type10 = TH14_SHARD, type7 = TH14_RING_BALL2.

const TIME_LIMIT: int = 3324;
const OPENING_BUFFER: int = 120;

const TH14_SHARD: int = 512;
const SHARD_COLOR: int = 6;

// GirlB01_at 每条 EX 记录的 VELTIME (0x200000): a=60, r=%C 目标标量速度, s 保留角.
// 方向不变时等价于 60 帧线性改变标量速度.
xformdef VELTIME_RAMP(target: fx) {
    step_speed(target, 60);
}

// st02.ecl.txt::GirlB01_at (299-339)
async sub girl_fire(step: angle) {
    var rank: int = global(GVAR_RANK);
    // diffI($D,5,5,8,15); diffI($E,2,10,10,10); !E 4 / !N 2 / !H 2 / !LO 1
    var volleys: int = 5;
    var per_volley: int = 2;
    var gap: int = 4;
    if rank == RANK_NORMAL {
        per_volley = 10;
        gap = 2;
    } else if rank == RANK_HARD {
        volleys = 8;
        per_volley = 10;
        gap = 2;
    } else if rank == RANK_LUNATIC {
        volleys = 15;
        per_volley = 10;
        gap = 1;
    }
    // %A = 1.5707964f + %RANDRAD / 30.0f; RANDRAD 为 [-pi,pi) 弧度, 一圈 BAM=65536.
    var aim: angle = (16384 + (rand(65536) - 32768) / 30) as angle;
    var k: int = 0;
    while k < volleys {
        // %C 每波重置为 1.0, 每颗 +0.35; etExSet 的 r 写 VELTIME 目标速度.
        var c: fx = 1fx;
        // ANIM type2 a=1 的出生退位移 position -= 4*velocity = 6.4px（沿弹角反推）.
        var ox: fx = -6.4fx * cos(aim);
        var oy: fx = -6.4fx * sin(aim);
        var i: int = 0;
        while i < per_volley {
            // etSprite(10,6) / etAim(0,1) / etCount(1,1) / etAngle(%A,0) / etSpeed(1.6,1.0)
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x + ox, $self_y + oy,
                     1.6fx, aim, VELTIME_RAMP(c), none);
            c = c + 0.35fx;
            i = i + 1;
        }
        aim = aim + step;
        wait(gap);
        k = k + 1;
    }
}

// st02.ecl.txt::GirlB01 (272-297)
async sub girl_b01(step: angle, mirrored: int) {
    set_invuln(65535);
    // setHurtbox(32,32) 普通圆取第一值*0.5 -> 16; setHitbox(24,24) -> 12.
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // moveVel(0.3926991f, 2.7f): 22.5 度; 镜像位在写入点把角换成 pi-angle.
    var dir: angle = 4096bam;
    if mirrored != 0 {
        dir = 32768bam - dir;
    }
    move_vel(0, dir, 2.7fx, EASE_LINEAR);
    // moveSpeedTime(60, 1, 0.0f): mode1=t^2 减速到 0.
    move_speed(60, 0fx, EASE_QUAD_IN);
    wait(60);
    spawn girl_fire(step);
    // moveAngle(-0.3926991f) 时速度恰为 0; move_vel(0,...,0) 同时写角并保持静速.
    var back: angle = -4096bam;
    if mirrored != 0 {
        back = 32768bam - back;
    }
    move_vel(0, back, 0fx, EASE_LINEAR);
    // moveSpeedTime(80, 1, 2.0f): mode1=t^2 加速到 2.
    move_speed(80, 2fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1); }
}

// st02.ecl.txt::MainSub04 (720-742): 4 轮, 每轮 0/120/240/360 创建 1/1/1/2 只 GirlB01.
async sub pattern() {
    wait(OPENING_BUFFER);
    // diffF(%F0, 0.2617994, 0.2617994, 0.20943952, 0.12217305)
    var v: angle = 15deg;
    var vn: angle = -15deg;
    // diffF(%F0, -0.5235988, -0.5235988, -0.34906584, -0.2617994)
    var w: angle = 30deg;
    var wn: angle = -30deg;
    if global(GVAR_RANK) == RANK_HARD {
        v = 12deg;
        vn = -12deg;
        w = 20deg;
        wn = -20deg;
    } else if global(GVAR_RANK) == RANK_LUNATIC {
        v = 7deg;
        vn = -7deg;
        w = 15deg;
        wn = -15deg;
    }
    var round: int = 0;
    while round < 4 {
        // enmCreateMF(224,80) 子镜像 1; enmCreateF(-224,80/-224,50) 子镜像 0.
        _ = spawn_enemy(224fx, 80fx, 200, 0, 0, 0, girl_b01(v, 1));
        wait(120);
        _ = spawn_enemy(-224fx, 80fx, 200, 0, 0, 0, girl_b01(vn, 0));
        wait(120);
        _ = spawn_enemy(-224fx, 50fx, 200, 0, 0, 0, girl_b01(vn, 0));
        wait(120);
        _ = spawn_enemy(-224fx, 50fx, 200, 0, 0, 0, girl_b01(wn, 0));
        _ = spawn_enemy(224fx, 50fx, 200, 0, 0, 0, girl_b01(w, 1));
        wait(120);
        round = round + 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
